import { Mesh, Plane, Group } from "three/webgpu";
import { MeshBasicNodeMaterial } from "three/webgpu";
import { gsap } from "gsap";
import {} from "@/primitives";
import {} from "@/text";

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Array<{name:string,params:any,trigger:string}>} [cinematicPrimitives]
 * @property {Array<any>} [textContent]
 * @property {any} [intent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {Object} textureLoader
 * @property {Function} textureLoader.loadTexture
 * @property {Object} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // root container
  const root = new Group();

  // store resources for cleanup
  const disposables = {
    geometry: null,
    material: null,
    texture: null,
    timelines: [],
    primitives: [],
  };

  // ---------- PRIMITIVES ----------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === "function") {
        const instance = fn(root, prim.params);
        disposables.primitives.push(instance);
      }
    }
  }

  // ---------- TEXT ----------
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize,
      color: item.role === "accent" ? "#ff2a38" : "#e8ecf2",
      align: "left",
    });
    root.add(txt);
  }

  // ---------- TEXTURED PLANE ----------
  if (config.imageUrl) {
    const geometry = new PlaneGeometry(1.6, 1.0);
    const material = new MeshBasicNodeMaterial({ map: null });
    const mesh = new Mesh(geometry, material);
    root.add(mesh);

    disposables.geometry = geometry;
    disposables.material = material;

    // async texture load (cached)
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
      disposables.texture = tex;
    });
  }

  // ---------- EVENT HANDLERS ----------
  root.userData.handlers = {};

  // ---------- CLEANUP ----------
  root.userData.cleanup = () => {
    // dispose primitives
    for (const p of disposables.primitives) {
      if (p && typeof p.cleanup === "function") p.cleanup();
    }

    // kill GSAP timelines
    for (const tl of disposables.timelines) {
      tl.kill();
    }

    // dispose material / geometry / texture
    if (disposables.material) disposables.material.dispose();
    if (disposables.geometry) disposables.geometry.dispose();
    if (disposables.texture) disposables.texture.dispose();
  };

  return root;
}
